const data = $('Webhook').first().json.body;
const args = data.args || {};
const intereses = args.intereses || {};

// Limpiar número (eliminar +)
const toNumberLimpio = (data.call?.from_number || '').replace('+', '');

// Concatenar el número y el contenido que escribió el cliente
const telefonoUsuario = args["telefono"] || '';
const telefonoFinal = `${toNumberLimpio} - ${telefonoUsuario}`;

// Corregir correo si viene escrito mal
let correo = args["correo"] || '';
correo = correo
  .toLowerCase()
  .replace(/\s?arroba\s?/gi, '@')
  .replace(/\s?punto\s?(com)?/gi, '.com')
  .replace(/\s+/g, '');

// Construimos resultado limpio
const resultado = {
  nombre_completo: args["nombre_completo"] || '',
  correo: correo,
  telefonoOrigen: toNumberLimpio,
  teléfono: telefonoFinal,
  ...intereses
};

return [
  {
    json: resultado
  }
];
